/*
 * Renders the page from window.SITE (content.js) and window.SITE_WRITING
 * (writing.js, generated by build.js from content/writing/*.md).
 * Content changes belong in those sources; this file only handles layout.
 */
(function () {
  "use strict";

  const SITE = window.SITE;
  if (!SITE) return;
  document.documentElement.classList.add("js");

  // ---------- Helpers ----------
  const $ = (sel, root = document) => root.querySelector(sel);
  const slot = (name) => $(`[data-slot="${name}"]`);

  const esc = (s) =>
    String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

  const isExternal = (url) => /^https?:/i.test(url);
  const linkAttrs = (url) => (isExternal(url) ? ' target="_blank" rel="noopener"' : "");

  const ICONS = {
    substack: '<path d="M22.539 8.242H1.46V5.406h21.08v2.836zM1.46 10.812V24L12 18.11 22.54 24V10.812H1.46zM22.54 0H1.46v2.836h21.08V0z"/>',
    medium: '<path d="M13.54 12a6.8 6.8 0 0 1-6.77 6.82A6.8 6.8 0 0 1 0 12a6.8 6.8 0 0 1 6.77-6.82A6.8 6.8 0 0 1 13.54 12zm7.42 0c0 3.54-1.51 6.42-3.38 6.42-1.87 0-3.39-2.88-3.39-6.42s1.52-6.42 3.39-6.42 3.38 2.88 3.38 6.42M24 12c0 3.17-.53 5.75-1.19 5.75-.66 0-1.19-2.58-1.19-5.75s.53-5.75 1.19-5.75C23.47 6.25 24 8.83 24 12z"/>',
    instagram: '<path fill-rule="evenodd" d="M7 2h10a5 5 0 0 1 5 5v10a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5V7a5 5 0 0 1 5-5Zm0 2a3 3 0 0 0-3 3v10a3 3 0 0 0 3 3h10a3 3 0 0 0 3-3V7a3 3 0 0 0-3-3H7Zm5 3.5a4.5 4.5 0 1 1 0 9 4.5 4.5 0 0 1 0-9Zm0 2a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5Zm5.3-4.1a1.3 1.3 0 1 1 0 2.6 1.3 1.3 0 0 1 0-2.6Z"/>',
    tiktok: '<path d="M12.525.02c1.31-.02 2.61-.01 3.91-.02.08 1.53.63 3.09 1.75 4.17 1.12 1.11 2.7 1.62 4.24 1.79v4.03c-1.44-.05-2.89-.35-4.2-.97-.57-.26-1.1-.59-1.62-.93-.01 2.92.01 5.84-.02 8.75-.08 1.4-.54 2.79-1.35 3.94-1.31 1.92-3.58 3.17-5.91 3.21-1.43.08-2.86-.31-4.08-1.03-2.02-1.19-3.44-3.37-3.65-5.71-.02-.5-.03-1-.01-1.49.18-1.9 1.12-3.72 2.58-4.96 1.66-1.44 3.98-2.13 6.15-1.72.02 1.48-.04 2.96-.04 4.44-.99-.32-2.15-.23-3.02.37-.63.41-1.11 1.04-1.36 1.75-.21.51-.15 1.07-.14 1.61.24 1.64 1.82 3.02 3.5 2.87 1.12-.01 2.19-.66 2.77-1.61.19-.33.4-.67.41-1.06.1-1.79.06-3.57.07-5.36.01-4.03-.01-8.05.02-12.07z"/>',
    linktree: '<path d="m13.736 5.853 4.005-4.117 2.325 2.38-4.2 4.005h5.908v3.305h-5.937l4.229 4.108-2.325 2.334-5.74-5.769-5.741 5.769-2.325-2.325 4.229-4.108H2.226V8.121h5.909l-4.2-4.004 2.324-2.381 4.005 4.117V0h3.472zm-3.472 10.306h3.472V24h-3.472z"/>',
    amazon: '<path fill-rule="evenodd" d="M5 2h12a3 3 0 0 1 3 3v15a1 1 0 0 1-1 1H6a3 3 0 0 1-3-3V4a2 2 0 0 1 2-2Zm0 2v14a1 1 0 0 0 1 1h12V5a1 1 0 0 0-1-1H5Zm3 3h7v2H8V7Z"/>',
    email: '<path fill-rule="evenodd" d="M3 4h18a1 1 0 0 1 1 1v14a1 1 0 0 1-1 1H3a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1Zm1 3.3V18h16V7.3l-8 5.2-8-5.2ZM5.8 6 12 10l6.2-4H5.8Z"/>',
    pdf: '<path d="M6 2h8l6 6v12a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2Zm7 1.5V9h5.5L13 3.5Z"/>',
    external: '<path d="M7 5h12v12h-2V8.4L6.7 18.7l-1.4-1.4L15.6 7H7V5Z"/>',
    read: '<path d="M4 11h12.2l-5.6-5.6L12 4l8 8-8 8-1.4-1.4 5.6-5.6H4v-2Z"/>',
  };
  const icon = (name) => `<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name] || ICONS.external}</svg>`;
  const AWARD = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="9" r="6"/><path d="M8.6 14 7 22l5-3 5 3-1.6-8"/></svg>';
  const ARROW = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>';

  const platformIcon = (label) => {
    const l = label.toLowerCase();
    if (l.includes("substack")) return "substack";
    if (l.includes("medium")) return "medium";
    if (l.includes("pdf")) return "pdf";
    return "external";
  };

  const KIND_LABELS = { essay: "Essay", oped: "Op-Ed", fiction: "Fiction", poetry: "Poetry", notes: "Notes" };
  const FILTER_LABELS = { all: "All", essay: "Essays", oped: "Op-Eds", fiction: "Fiction", poetry: "Poetry", notes: "Notes" };

  // Pieces with body text are read on this site; the rest link out.
  const primaryLink = (w) => (w.url ? { label: "Read", url: w.url } : w.links[0]);

  const fmtDate = (item, opts = { month: "short", day: "numeric", year: "numeric" }) => {
    if (item.dateLabel) return item.dateLabel;
    if (!item.date) return "";
    const d = new Date(item.date + "T12:00:00");
    return d.toLocaleDateString("en-US", opts);
  };

  // Newest first; undated pieces keep their listed order at the end.
  const writing = (window.SITE_WRITING || [])
    .map((w, i) => ({ ...w, _i: i }))
    .sort((a, b) => {
      if (a.date && b.date) return b.date.localeCompare(a.date) || a._i - b._i;
      if (a.date) return -1;
      if (b.date) return 1;
      return a._i - b._i;
    });

  // ---------- Hero ----------
  slot("roles").textContent = SITE.person.roles.join(" · ");

  slot("latest").innerHTML = writing
    .filter((w) => w.date && !w.dateLabel)
    .slice(0, 3)
    .map((w) => {
      const link = primaryLink(w);
      const where = w.url ? KIND_LABELS[w.kind] : link.label;
      return `<li><a href="${esc(link.url)}"${linkAttrs(link.url)}>
        <span class="latest-title">${esc(w.title)}</span>
        <span class="latest-meta">${esc(where)} · ${esc(fmtDate(w, { month: "short", year: "numeric" }))}</span>
      </a></li>`;
    })
    .join("");

  slot("published-in").innerHTML = SITE.about.publishedIn
    .map((p) => `<span class="pub">${esc(p)}</span>`)
    .join(' <span class="sep" aria-hidden="true">/</span> ');

  // ---------- Featured film ----------
  const f = SITE.featuredFilm;
  if (f) {
    slot("featured-film").innerHTML = `
      <div class="film-hero">
        <img src="${esc(f.image)}" alt="${esc(f.imageAlt)}" loading="lazy">
        <div class="wrap">
          <p class="eyebrow">Now in development · Feature screenplay</p>
          <h2 class="film-title" id="film-title">${esc(f.title)}</h2>
          <span class="film-status">${esc(f.status)}</span>
        </div>
      </div>
      <div class="wrap film-body">
        <div>
          <p class="film-logline">${esc(f.logline)}</p>
          <div class="film-about">${f.about.map((p) => `<p>${esc(p)}</p>`).join("")}</div>
          <p class="film-credits">${esc(f.credits)}</p>
          ${f.collaborator ? `<p class="collab"><strong>Co-director.</strong> ${esc(f.collaborator)}</p>` : ""}
        </div>
        <aside class="film-side">
          <ul class="laurels">${f.laurels.map((l) => `<li>${AWARD}<span>${esc(l)}</span></li>`).join("")}</ul>
          <div class="film-actions">
            ${f.actions
              .map((a) => `<a class="btn${a.primary ? " btn-primary" : ""}" href="${esc(a.url)}"${linkAttrs(a.url)}>${esc(a.label)}</a>`)
              .join("")}
          </div>
          ${f.sponsor ? `<div class="sponsor"><span>${esc(f.sponsor.name)}</span><img src="${esc(f.sponsor.logo)}" alt="The Gotham Film &amp; Media Institute" loading="lazy"></div>` : ""}
        </aside>
      </div>`;
  }

  // ---------- Screen & stage ----------
  const textLink = (l) => {
    if (l.internal) {
      return `<a class="text-link" href="${esc(l.url)}"${l.filter ? ` data-filter="${esc(l.filter)}"` : ""}>${esc(l.label)} ${ARROW}</a>`;
    }
    return `<a class="text-link" href="${esc(l.url)}"${linkAttrs(l.url)}>${esc(l.label)} ${ARROW}</a>`;
  };

  slot("screen").innerHTML = SITE.screen
    .map(
      (w) => `
      <article class="work reveal${w.image ? "" : " work-noimg"}">
        ${w.image ? `<div class="work-media"><img src="${esc(w.image)}" alt="${esc(w.imageAlt || "")}" loading="lazy"></div>` : ""}
        <div class="work-body">
          <p class="work-kind">${esc(w.kind)}</p>
          <h3>${esc(w.title)}</h3>
          ${w.role ? `<p class="work-role">${esc(w.role)}</p>` : ""}
          ${(w.laurels || []).map((l) => `<p class="work-laurel">${AWARD}<span>${esc(l)}</span></p>`).join("")}
          <p class="work-summary">${esc(w.summary)}</p>
          ${w.quote ? `<blockquote class="work-quote">“${esc(w.quote.text)}”<cite>— ${esc(w.quote.source)}</cite></blockquote>` : ""}
          ${
            w.festivals
              ? `<details><summary>Screened at ${w.festivals.length} festivals</summary><ul>${w.festivals
                  .map((x) => `<li>${esc(x)}</li>`)
                  .join("")}</ul></details>`
              : ""
          }
          ${w.links ? `<div class="work-links">${w.links.map(textLink).join("")}</div>` : ""}
        </div>
      </article>`
    )
    .join("");

  // ---------- Books ----------
  slot("books").innerHTML = SITE.books
    .map(
      (b) => `
      <article class="book reveal">
        <div class="book-cover"><img src="${esc(b.cover)}" alt="Cover of ${esc(b.title)}" loading="lazy"></div>
        <div>
          <p class="eyebrow">${esc(b.kind)}</p>
          <h3>${esc(b.title)}</h3>
          ${b.subtitle ? `<p class="book-subtitle">${esc(b.subtitle)}</p>` : ""}
          ${b.badge ? `<p class="book-badge">${esc(b.badge)}</p>` : ""}
          <div class="book-desc">${b.description.map((p) => `<p>${esc(p)}</p>`).join("")}</div>
          ${b.quote ? `<blockquote class="book-quote">“${esc(b.quote.text)}”<cite>— ${esc(b.quote.source)}</cite></blockquote>` : ""}
          ${b.epigraph ? `<blockquote class="book-quote">“${esc(b.epigraph.text)}”<cite>— ${esc(b.epigraph.source)}</cite></blockquote>` : ""}
          <div class="book-buy">
            ${b.buy.map((l, i) => `<a class="btn${i === 0 ? " btn-primary" : ""}" href="${esc(l.url)}"${linkAttrs(l.url)}>${esc(l.label)}</a>`).join("")}
          </div>
        </div>
      </article>`
    )
    .join("");

  if (SITE.reviews?.length) {
    slot("reviews").innerHTML =
      `<p class="eyebrow reviews-title">Readers on <em>A World Between</em></p>` +
      SITE.reviews
        .map(
          (r) => `<blockquote class="review reveal"><span class="stars" aria-label="Five stars">★★★★★</span>“${esc(r.text)}”<cite>— ${esc(r.source)}</cite></blockquote>`
        )
        .join("");
  }

  // ---------- Writing ----------
  const PAGE = 9;
  const state = { kind: "all", q: "", limit: PAGE };
  const grid = slot("writing");
  const moreBtn = slot("more");
  const searchInput = slot("search");

  const kinds = ["all", ...Object.keys(KIND_LABELS).filter((k) => writing.some((w) => w.kind === k))];
  const filtersEl = slot("filters");
  filtersEl.innerHTML = kinds
    .map((k) => {
      const n = k === "all" ? writing.length : writing.filter((w) => w.kind === k).length;
      return `<button class="chip" type="button" data-kind="${k}" aria-pressed="${k === state.kind}">${FILTER_LABELS[k]}<span class="count">${n}</span></button>`;
    })
    .join("");

  const pieceCard = (w) => {
    const primary = primaryLink(w);
    const meta = [`<span class="piece-kind">${KIND_LABELS[w.kind] || ""}</span>`];
    const date = fmtDate(w);
    if (date) meta.push(`<span>${esc(date)}</span>`);
    return `
      <article class="piece reveal${w.image ? "" : " piece-noimg"}">
        ${w.image ? `<div class="piece-media"><img src="${esc(w.image)}" alt="" loading="lazy"${w.imagePosition ? ` style="object-position:${esc(w.imagePosition)}"` : ""}></div>` : ""}
        <div class="piece-body">
          <p class="piece-meta">${meta.join("")}</p>
          <h3><a href="${esc(primary.url)}"${linkAttrs(primary.url)}>${esc(w.title)}</a></h3>
          ${w.venue ? `<p class="piece-venue">${esc(w.venue)}</p>` : ""}
          ${w.dek ? `<p class="piece-dek">${esc(w.dek)}</p>` : ""}
          <div class="piece-links">
            ${w.url ? `<a class="platform platform-read" href="${esc(w.url)}">${icon("read")}Read</a>` : ""}
            ${w.links
              .map(
                (l) =>
                  `<a class="platform" href="${esc(l.url)}"${linkAttrs(l.url)} aria-label="Read “${esc(w.title)}” on ${esc(l.label)}">${icon(platformIcon(l.label))}${esc(l.label)}</a>`
              )
              .join("")}
          </div>
        </div>
      </article>`;
  };

  function renderWriting() {
    const q = state.q.trim().toLowerCase();
    const matches = writing.filter(
      (w) =>
        (state.kind === "all" || w.kind === state.kind) &&
        (!q || [w.title, w.dek, w.venue].join(" ").toLowerCase().includes(q))
    );
    const shown = matches.slice(0, state.limit);
    grid.innerHTML = shown.length
      ? shown.map(pieceCard).join("")
      : `<p class="writing-empty">Nothing matches “${esc(state.q)}”.</p>`;
    moreBtn.hidden = matches.length <= state.limit;
    moreBtn.textContent = `Show more (${matches.length - shown.length})`;
    filtersEl.querySelectorAll(".chip").forEach((c) => c.setAttribute("aria-pressed", String(c.dataset.kind === state.kind)));
    observe(grid.querySelectorAll(".reveal"));
  }

  function setKind(kind) {
    state.kind = kind;
    state.limit = PAGE;
    renderWriting();
  }

  filtersEl.addEventListener("click", (e) => {
    const chip = e.target.closest(".chip");
    if (chip) setKind(chip.dataset.kind);
  });
  searchInput.addEventListener("input", () => {
    state.q = searchInput.value;
    state.limit = PAGE;
    renderWriting();
  });
  moreBtn.addEventListener("click", () => {
    state.limit += PAGE;
    renderWriting();
  });
  // Links elsewhere on the page (e.g. "Read the story") can pre-select a filter.
  document.addEventListener("click", (e) => {
    const a = e.target.closest("a[data-filter]");
    if (a) setKind(a.dataset.filter);
  });

  // ---------- About ----------
  const ab = SITE.about;
  slot("about").insertAdjacentHTML(
    "beforeend",
    `<div class="about-copy reveal">
       <p class="about-lead">${esc(ab.lead)}</p>
       ${ab.paragraphs.map((p) => `<p>${esc(p)}</p>`).join("")}
     </div>
     <blockquote class="about-voice reveal">
       ${ab.voice.map((p) => `<p>${esc(p)}</p>`).join("")}
       <cite>— Robert, in his own words</cite>
     </blockquote>`
  );

  // ---------- Follow, contact, footer ----------
  slot("newsletter-blurb").textContent = SITE.newsletter.blurb;
  slot("newsletter-link").href = SITE.newsletter.url;
  const email = slot("email");
  email.href = `mailto:${SITE.person.email}`;
  email.textContent = SITE.person.email;

  slot("social").innerHTML = SITE.social
    .map(
      (s) => `<li><a href="${esc(s.url)}"${linkAttrs(s.url)}>${icon(s.id)}<span><span class="social-name">${esc(s.label)}</span><span class="social-handle">${esc(s.handle)}</span></span></a></li>`
    )
    .join("");

  slot("footer-social").innerHTML = [...SITE.social, { id: "email", label: "Email", url: `mailto:${SITE.person.email}` }]
    .map((s) => `<li><a href="${esc(s.url)}"${linkAttrs(s.url)} aria-label="${esc(s.label)}">${icon(s.id)}</a></li>`)
    .join("");

  slot("year").textContent = new Date().getFullYear();

  // ---------- Header & menu ----------
  const header = $(".site-header");
  const nav = $("#site-nav");
  const toggle = $(".menu-toggle");
  const onScroll = () => header.classList.toggle("scrolled", window.scrollY > 8);
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();
  toggle.addEventListener("click", () => {
    const open = nav.classList.toggle("open");
    toggle.setAttribute("aria-expanded", String(open));
  });
  nav.addEventListener("click", (e) => {
    if (e.target.closest("a")) {
      nav.classList.remove("open");
      toggle.setAttribute("aria-expanded", "false");
    }
  });

  // ---------- Reveal on scroll ----------
  const io =
    "IntersectionObserver" in window
      ? new IntersectionObserver(
          (entries) =>
            entries.forEach((en) => {
              if (en.isIntersecting) {
                en.target.classList.add("in");
                io.unobserve(en.target);
              }
            }),
          { rootMargin: "0px 0px -8% 0px" }
        )
      : null;
  function observe(nodes) {
    nodes.forEach((n) => (io ? io.observe(n) : n.classList.add("in")));
  }

  renderWriting();
  observe(document.querySelectorAll(".reveal"));
})();
